bg=4
out=[[bg]*22 for _ in range(22)]
# square outer, inner, top-left row/col
objs=[(8,2,1,0),(8,3,5,5),(8,9,14,0),(2,9,0,17),(2,6,8,12),(2,7,12,17)]
for border,inner,r,c in objs:
    for i in range(5):
        for j in range(5):
            out[r+i][c+j] = inner if 1<=i<=3 and 1<=j<=3 else border
print('\n'.join(' '.join(map(str,row)) for row in out))
